mapper.select:


    and platform = #{platform}

        and (account_name like concat('%', #{accountName}, '%') or account_code like concat('%', #{accountName}, '%'))

    and persona = #{persona}
    and paused = #{paused}
    and status = #{status}

order by account_id

select count(*) from abr_publish_record
where account_id = #{accountId}
  and ((status = 'scheduled' and planned_time >= #{from} and planned_time < #{to})
    or (status = 'published' and published_time >= #{from} and published_time < #{to}))
  and record_id <> #{excludeRecordId}
